import React, { useState, useEffect, useRef } from 'react';
import './Header.css';

const searchIndex = [
  { label: 'Tableau de bord', type: 'Menu', action: 'dashboard' },
  { label: 'Entreprise & Flotte', type: 'Menu', action: 'entreprise' },
  { label: 'Transactions', type: 'Menu', action: 'transactions' },
  { label: 'Demandes de trajets', type: 'Menu', action: 'demandes' },
  { label: 'Patients', type: 'Menu', action: 'patients' },
  { label: 'Calendrier', type: 'Menu', action: 'calendrier' },
  { label: 'Mon Profil', type: 'Menu', action: 'profil' },
  { label: 'Créer une nouvelle demande', type: 'Action', action: 'demandes' },
  { label: 'Ajouter un patient', type: 'Action', action: 'patients' },
  { label: 'Marie Dubois', type: 'Patient', action: 'patients' },
  { label: 'François Dupont', type: 'Patient', action: 'patients' }
];

const Header = ({ user, onNavigate }) => {
  const [query, setQuery] = useState('');
  const [showDropdown, setShowDropdown] = useState(false);
  const searchRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (searchRef.current && !searchRef.current.contains(event.target)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filteredResults = query.trim() === ''
    ? []
    : searchIndex.filter(item => item.label.toLowerCase().includes(query.toLowerCase()));

  const handleSelect = (action) => {
    if (onNavigate) onNavigate(action);
    setQuery('');
    setShowDropdown(false);
  };
  return (
    <header className="header">
      <div className="search-container" ref={searchRef}>
        <div className="search-box">
          <span className="search-icon">🔍</span>
          <input
            type="text"
            placeholder="Rechercher (ex: Patients, Profil...)"
            className="search-input"
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setShowDropdown(true);
            }}
            onFocus={() => setShowDropdown(true)}
          />
        </div>

        {showDropdown && query.trim() !== '' && (
          <div className="search-dropdown">
            {filteredResults.length > 0 ? (
              filteredResults.map((item, index) => (
                <div
                  key={index}
                  className="search-dropdown-item"
                  onClick={() => handleSelect(item.action)}
                >
                  <div className="search-item-info">
                    <span className="search-item-icon">
                      {item.type === 'Menu' ? '📁' : item.type === 'Action' ? '⚡' : '👤'}
                    </span>
                    <span className="search-item-label">{item.label}</span>
                  </div>
                  <span className="search-item-type">{item.type}</span>
                </div>
              ))
            ) : (
              <div className="search-dropdown-empty">Aucun résultat trouvé pour "{query}"</div>
            )}
          </div>
        )}
      </div>

      <div className="header-actions">
        {user && (
          <div style={{ marginRight: '16px', fontWeight: '500', color: '#1e293b' }}>
            Bonjour, {user.firstName} 👋
          </div>
        )}
        <div className="notification-icon">
          🔔
          <span className="notification-badge">1</span>
        </div>
      </div>
    </header>
  );
};

export default Header;
